-- Hyprland config (Lua, Hyprland 0.53+). Linked to ~/.config/hypr by install.sh.
-- Split into modules next to this file:
--   binds.lua   generated by keys/build.py from keys/keymap.toml (don't edit; edit the keymap)
--   colors.lua  generated by theme/build.py from theme/gruver16.yaml (don't edit)
--   kde.lua     KDE app integration
--   settings.lua  written by the Quickshell settings app (applied last)
-- Check without logging in:  Hyprland --verify-config -c ~/.config/hypr/hyprland.lua

local c = require("colors")
local rgb = function(hex, alpha) return "rgba(" .. hex .. (alpha or "ff") .. ")" end

----------------------
---- PROGRAMS --------
----------------------

local programs = {
    terminal     = "ghostty",
    -- Cmd+Space: the Quickshell command palette (quickshell/CommandPalette.qml).
    -- Cmd+Opt+Space: Vicinae, the backup.
    launcher     = "qs ipc call palette toggle",
    launcher_alt = "vicinae toggle",
}

------------------
---- MONITORS ----
------------------

-- Fallback for any monitor. Per-monitor modes are set in the settings app (settings.lua, applied
-- at the end of this file).
hl.monitor({ output = "", mode = "preferred", position = "auto", scale = "auto" })
-- The TV mirrors the Samsung (one set of desktops, shown on both).
hl.monitor({ output = "desc:Sony SONY TV", mode = "preferred", position = "auto", scale = 1, mirror = "DP-4" })

-------------------
---- AUTOSTART ----
-------------------

-- GTK 4 apps draw with GTK's GL renderer instead of its default Vulkan one, which on this NVIDIA
-- card sometimes paints parts of a window black (Ghostty's active tab flickering black). Also
-- passed to systemd below, since Ghostty windows can be started through D-Bus.
hl.env("GSK_RENDERER", "ngl")

hl.on("hyprland.start", function()
    -- Let systemd user services see this session, then swap Toshy (it starts at login; KDE still
    -- uses it) for mackeys, the keyboard remapper for Hyprland (keys/remap.toml, keys/daemon).
    -- Toshy's session monitor starts Toshy again when it sees a session, so it stops first.
    hl.exec_cmd("dbus-update-activation-environment --systemd XDG_SESSION_TYPE XDG_SESSION_DESKTOP "
        .. "XDG_CURRENT_DESKTOP WAYLAND_DISPLAY DISPLAY HYPRLAND_INSTANCE_SIGNATURE "
        .. "QT_QPA_PLATFORMTHEME XDG_MENU_PREFIX GSK_RENDERER "
        .. "&& systemctl --user stop toshy-session-monitor.service toshy-config.service && systemctl --user restart mackeys.service")
    -- Hyprland-only Ghostty look (see the end of ghostty/config.ghostty).
    hl.exec_cmd("ln -sfn hyprland.ghostty ~/.config/ghostty/session.ghostty")
    hl.exec_cmd("vicinae server")
    hl.exec_cmd("qs") -- Quickshell: bar (quickshell/ in dotfiles)
    hl.exec_cmd("hypridle") -- screen off after 2 idle hours (hypridle.conf)
    -- Plugins (hymission, HyprCapture, hyprglass), installed with hyprpm (built against this
    -- exact Hyprland; after a Hyprland update run `hyprpm update`). Their settings are applied
    -- once they're loaded (hl.plugin.<name> exists from then on).
    hl.exec_cmd("command -v hyprpm >/dev/null && hyprpm reload -n && hyprctl reload")
    -- leftover mission control flags (hypr/overview-flag.sh) would keep Toshy's h/j/k/l -> arrows on
    hl.exec_cmd("rm -f $XDG_RUNTIME_DIR/hymission-open $XDG_RUNTIME_DIR/hymission-search")
    -- mission control's search box looks like the shell (hymission-search.css); KDE may rewrite
    -- gtk.css, so add the import again when it's missing
    hl.exec_cmd("f=~/.config/gtk-4.0/gtk.css; mkdir -p ${f%/*}; touch $f; grep -q hymission-search $f "
        .. "|| sed -i '1i @import url(\"../hypr/hymission-search.css\");' $f")
end)

require("kde")

-----------------------
---- LOOK AND FEEL ----
-----------------------

hl.config({
    general = {
        gaps_in     = 4,
        gaps_out    = 8,
        border_size = 2,
        col = {
            active_border   = rgb(c.base0D),
            inactive_border = rgb(c.base03),
        },
        resize_on_border = true,
        layout = "dwindle",
    },
    decoration = {
        rounding = 8,
        shadow = { enabled = true, range = 8, render_power = 3, color = rgb("000000", "88") },
        blur   = { enabled = true, size = 3, passes = 1 },
    },
    animations = { enabled = true },
    dwindle = { preserve_split = true },
    misc = {
        force_default_wallpaper = 0,     -- no anime mascot wallpapers
        disable_hyprland_logo   = true,
        background_color        = rgb(c.base00), -- shown where there's no wallpaper
    },
    -- Don't switch the monitor to HDR when something goes fullscreen (default): the switch is a
    -- modeset (black for seconds) and SDR content looks dimmer in HDR mode.
    render = { cm_auto_hdr = 0 },
})

-- Animation curves the settings app can pick from (quickshell/Settings.qml: `curves`, keep in
-- sync). Defining them changes nothing until an animation uses one.
hl.curve("easeOutQuint",   { type = "bezier", points = { {0.23, 1},    {0.32, 1} } })
hl.curve("easeInOutCubic", { type = "bezier", points = { {0.65, 0.05}, {0.36, 1} } })
hl.curve("almostLinear",   { type = "bezier", points = { {0.5, 0.5},   {0.75, 1} } })
hl.curve("quick",          { type = "bezier", points = { {0.15, 0},    {0.1, 1} } })
hl.curve("overshoot",      { type = "bezier", points = { {0.05, 0.9},  {0.1, 1.1} } })
hl.curve("easy",           { type = "spring", mass = 1, stiffness = 238.1191, damping = 24.21279333 })
hl.curve("bouncy",         { type = "spring", mass = 1, stiffness = 200, damping = 10 })
local springs = { easy = true, bouncy = true }

---------------
---- INPUT ----
---------------

hl.config({
    input = {
        -- Same layouts as KDE: US and Swedish (swerty). Opt+Space switches (see keys/keymap.toml).
        kb_layout  = "us,se",
        kb_variant = ",swerty",
        -- Caps is Esc / Ctrl (keys/remap.toml) and never Caps Lock, even when the raw keyboard
        -- reaches Hyprland (while mackeys starts or restarts).
        kb_options = "ctrl:nocaps",
        -- Click to focus, like a Mac: hovering doesn't focus windows (scrolling still goes to the
        -- window under the pointer), and keyboard focus changes (Cmd+Tab, Opt+H/J/K/L) never move
        -- the pointer.
        follow_mouse = 2,
        sensitivity  = 0,
    },
    cursor = { no_warps = true },
})

---------------------
---- KEYBINDINGS ----
---------------------

-- Everything keyboard-related lives in keys/keymap.toml -> binds.lua.
require("binds")(programs)

-- App switcher (quickshell/AppSwitcher.qml): Cmd+Tab arrives as ALT+Tab (binds.lua). The switcher
-- sees Alt (= Cmd) being let go itself; this release bind is a fallback (Hyprland skips it when
-- another key was pressed in between). Does nothing when the switcher isn't open.
for _, key in ipairs({ "Alt_L", "Alt_R" }) do
    hl.bind("ALT + " .. key, hl.dsp.global("quickshell:switcher-commit"), { release = true })
end

-- Mouse: Opt + left-drag moves a window, Opt + right-drag resizes it.
hl.bind("ALT + mouse:272", hl.dsp.window.drag(),   { mouse = true })
hl.bind("ALT + mouse:273", hl.dsp.window.resize(), { mouse = true })

-- Media keys: volume, mute and play/pause are the F-row's (keys/keymap.toml); next/previous
-- track only come from other devices (the F-row's F7/F9 seek instead).
hl.bind("XF86AudioNext",        hl.dsp.exec_cmd("playerctl next"),                                  { locked = true })
hl.bind("XF86AudioPrev",        hl.dsp.exec_cmd("playerctl previous"),                              { locked = true })

--------------------
---- WORKSPACES ----
--------------------

-- Desktops 1-5 always exist, even empty (keys/keymap.toml: desktops = 5): mission control's
-- strip shows all five and can switch to an empty one (it fails on one that doesn't exist yet).
for i = 1, 5 do
    hl.workspace_rule({ workspace = tostring(i), persistent = true })
end

-----------------
---- WINDOWS ----
-----------------

hl.window_rule({
    -- Ignore maximize requests from apps; tiling decides sizes.
    name  = "suppress-maximize-events",
    match = { class = ".*" },
    suppress_event = "maximize",
})

hl.window_rule({
    -- Fix some dragging issues with XWayland
    name  = "fix-xwayland-drags",
    match = { class = "^$", title = "^$", xwayland = true, float = true, fullscreen = false, pin = false },
    no_focus = true,
})

----------------
---- LAYERS ----
----------------

hl.layer_rule({
    -- Quickshell bar is translucent; blur the painting behind it (frosted wall label).
    name  = "blur-quickshell-bar",
    match = { namespace = "^quickshell-bar$" },
    blur  = true,
})

hl.layer_rule({
    -- Opt+? cheat sheet: blur the desktop behind it.
    name  = "blur-quickshell-keybinds",
    match = { namespace = "^quickshell-keybinds$" },
    blur  = true,
})

hl.layer_rule({
    -- Notification cards are slightly translucent; blur what's behind them.
    name  = "blur-quickshell-notifications",
    match = { namespace = "^quickshell-notifications$" },
    blur  = true,
})

hl.layer_rule({
    name  = "blur-quickshell-switcher",
    match = { namespace = "^quickshell-switcher$" },
    blur  = true,
})

hl.layer_rule({
    name  = "blur-quickshell-palette",
    match = { namespace = "^quickshell-palette$" },
    blur  = true,
})

hl.layer_rule({
    name  = "blur-quickshell-controlcenter",
    match = { namespace = "^quickshell-controlcenter$" },
    blur  = true,
})

-- Quickshell settings app (quickshell/Settings.qml): a floating window, not tiled.
hl.window_rule({
    name  = "float-quickshell-settings",
    match = { class = "^org\\.quickshell$", title = "^Settings$" },
    float = true,
    size  = "900 620",
    center = true,
})

-----------------
---- PLUGINS ----
-----------------

-- Installed with hyprpm and loaded at start (start block above, which re-reads this file after
-- loading them). Each part only runs once its plugin is loaded.

-- Liquid glass (hyprglass) under the shell's panels (Quickshell layers; quickshell/Theme.qml keeps
-- their backgrounds see-through) and under windows while they're unfocused (90% opacity).
-- Light or dark glass follows dark mode (hypr/appearance.sh switches it while running).
if hl.plugin.hyprglass then
    local hg = hl.plugin.hyprglass
    local p = io.popen("gsettings get org.gnome.desktop.interface color-scheme 2>/dev/null")
    local scheme = p and p:read("*a") or ""
    if p then p:close() end
    -- The look (style, blur, refraction, ...) is set in the settings window's Glass page
    -- (settings.lua, applied below). A style other than "default" sets most values itself.
    hg.config({
        default_theme = scheme:find("dark") and "dark" or "light",
        default_preset = "pomme",      -- Apple-like
        skip_opaque_windows = false,   -- apps mark their windows opaque even at 90% opacity
        layers = { enabled = true },
    })
    for _, ns in ipairs({ "quickshell-bar", "quickshell-controlcenter", "quickshell-palette",
                          "quickshell-switcher", "quickshell-notifications" }) do
        hg.layer(ns, {})
    end
    -- the Opt+? sheet dims the whole screen (35%): glass only under the card
    hg.layer("quickshell-keybinds", { mask_mode = "alpha", mask_threshold = 0.5 })
end

-- Mission control (hymission; keys/keymap.toml: overview.*, set up in keys/build.py): the windows
-- spread out with a strip of all five desktops along the top (drag a window onto one to move it).
-- F3 = this desktop, no search box: the mouse, the arrows and h/j/k/l or Opt+h/j/k/l (Toshy)
-- move real focus, 1-9 pick a window, / starts a search. F4 = all desktops with a search box (styled by hymission-search.css): type part of a
-- title or app name, Enter goes there. Esc closes; Opt+Tab switches desktop (leftmost window).
if hl.plugin.hymission then
    hl.config({ plugin = { hymission = {
        workspace_strip_anchor = "top",
        -- F4 (all desktops): one row per desktop, in desktop order. While its search box is up,
        -- the keys can only step through hymission's list (Up/Down), which is in this order, so
        -- next/previous then reads left to right, row by row
        one_workspace_per_row = 1,
        multi_workspace_sort_recent_first = 0,
        -- only the selected window grows (in F4 the selection doesn't follow the pointer; a hovered
        -- window growing too would look like a second selection)
        hover_expand_scale = 1.0,
    } } })
end

-- Screenshots (HyprCapture, on the screenshot key; keys/keymap.toml): drag an area or click a
-- window, saved and named like macOS does, copied, with a thumbnail in the corner.
if hl.plugin.hyprcapture then
    hl.config({ plugin = { hyprcapture = {
        default_mode = "region",
        fusion_mode = true,            -- drag = area, click = that window
        save = true,
        clipboard = true,
        show_thumbnail = true,
        save_dir = os.getenv("HOME") .. "/Pictures/Screenshots",
        filename_template = "Screenshot %Y-%m-%d at %H.%M.%S.png",
    } } })
end

------------------
---- SETTINGS ----
------------------

-- Written by the settings app; applied last so it wins over the values above.
-- options: { ["general:gaps_in"] = 6 } -> hl.config({ general = { gaps_in = 6 } })
local settings = require("settings")
for key, value in pairs(settings.options or {}) do
    -- a plugin's options only exist once it's loaded (this file runs again then)
    local plugin = key:match("^plugin:([^:]+):")
    if plugin and not hl.plugin[plugin] then goto continue end
    local root, parts = {}, {}
    local node = root
    for part in key:gmatch("[^:]+") do parts[#parts + 1] = part end
    for i = 1, #parts - 1 do
        node[parts[i]] = {}
        node = node[parts[i]]
    end
    node[parts[#parts]] = value
    hl.config(root)
    ::continue::
end
-- animations: { ["windowsIn"] = { enabled = true, speed = 4, curve = "easy", style = "popin 80%" } }
for leaf, a in pairs(settings.animations or {}) do
    local spec = { leaf = leaf, enabled = a.enabled, speed = a.speed }
    if a.style and a.style ~= "" then spec.style = a.style end
    if springs[a.curve] then spec.spring = a.curve else spec.bezier = a.curve or "default" end
    hl.animation(spec)
end
for output, m in pairs(settings.monitors or {}) do
    hl.monitor({ output = output, mode = m.mode, position = m.position or "auto", scale = m.scale or "auto" })
end
